-- ════════════════════════════════════════════════════════════════════════════
--  Las parroquias, recortadas por la línea de costa.
--
--  POR QUÉ. Máximo, mirando el mapa el 23/10/2026: «estás delimitando Olegario
--  y Santa Lucía hasta el mar y allá no se limpia». Tenía razón: el límite
--  legal de una parroquia ribereña entra al Lago de Maracaibo, y medido acá
--  resultó ser la MITAD de su superficie:
--      Olegario Villalobos  18,66 km² → 9,42 km²  (-50%)
--      Santa Lucía           9,39 km² → 4,18 km²  (-55%)
--      Caracciolo y Venancio: sin cambio (no son ribereñas)
--
--  ⛔ EL LÍMITE OFICIAL NO SE PIERDE. Se guarda en `poligono_oficial`. Ante la
--     Alcaldía el que vale es ése: es la parroquia de verdad. El recortado es
--     para OPERAR y para medir cobertura, y la diferencia queda explicable.
--     [[norma-un-valor-derivado-depende-de-la-version-de-su-regla]]
--
--  El recorte sale de la línea de costa de OpenStreetMap (`natural=coastline`,
--  1.816 puntos en el tramo), no de una línea dibujada a ojo.
-- ════════════════════════════════════════════════════════════════════════════

alter table parroquias add column if not exists poligono_oficial jsonb;

comment on column parroquias.poligono_oficial is
  'El limite ADMINISTRATIVO tal como lo publica OpenStreetMap, que en las parroquias '
  'riberenas entra al lago. `poligono` es el mismo recortado por la costa, que es donde '
  'se recoge. Ante la Alcaldia manda el oficial.';

-- Se guarda el oficial ANTES de tocar nada, y solo la primera vez.
update parroquias set poligono_oficial = poligono
 where poligono_oficial is null and es_nuestra;
