-- ── CONTROL: el recorte no puede haberse comido tierra ──────────────────────
-- ⛔ La prueba que decide. Si al recortar se perdio terreno donde SI trabajan
--    los camiones, las posiciones que el geocodificador del PROVEEDOR ubica en
--    esa parroquia empezarian a caer FUERA del poligono. Se compara contra el
--    mismo cruce que valido los limites cuando se cargaron: tenia 89-100%.
do $$
declare r record; poli jsonb; dentro int; total int; txt text := ''; malas int := 0;
begin
  for r in select nombre from parroquias where es_nuestra order by nombre loop
    select poligono into poli from parroquias where nombre = r.nombre;
    select count(*) filter (where _punto_en_poligono(lat, lon, poli)), count(*)
      into dentro, total
      from (select lat, lon from gps_posiciones
             where ubicacion like '%' || r.nombre || '%' limit 120) p;
    if total = 0 then continue; end if;
    if dentro::numeric / total < 0.80 then
      malas := malas + 1;
    end if;
    txt := txt || r.nombre || ': ' || dentro || '/' || total || '; ';
  end loop;
  if malas > 0 then
    raise exception 'CONTROL: % parroquia(s) perdieron sus propias posiciones al recortar. El recorte se comio tierra. %', malas, txt;
  end if;

  -- Y el oficial tiene que haber quedado guardado en las cuatro.
  if (select count(*) from parroquias where es_nuestra and poligono_oficial is null) > 0 then
    raise exception 'CONTROL: alguna parroquia quedo sin su limite oficial guardado';
  end if;

  -- El recortado NO puede ser igual al oficial en las riberenas: si lo fuera,
  -- el recorte no se aplico y el mapa seguiria llegando al lago.
  if (select count(*) from parroquias
       where nombre in ('Parroquia Olegario Villalobos','Parroquia Santa Lucía')
         and poligono = poligono_oficial) > 0 then
    raise exception 'CONTROL: una parroquia riberena quedo igual al oficial: no se recorto';
  end if;

  raise notice 'OK - recortadas y con su limite oficial guardado. Posiciones adentro: %', txt;
end $$;